import{_ as s,o as i,c as e,aO as d}from"./chunks/framework.BFrk9dwu.js";const r="/recipes/roasted-fish.jpg",a="/recipes/roasted-fish/step-1-a.jpg",u=JSON.parse('{"title":"烤鱼","description":"黑鱼开背腌好下锅煎到两面金黄，火锅底料炒出红油，配菜垫底浇上去的家常烤鱼做法，含鱼皮粘锅、肉散、汤寡的排查","frontmatter":{"date":"2026-11-29T03:04:05.000Z","title":"烤鱼","description":"黑鱼开背腌好下锅煎到两面金黄，火锅底料炒出红油，配菜垫底浇上去的家常烤鱼做法，含鱼皮粘锅、肉散、汤寡的排查","categories":["life","recipes"],"permalink":"/pages/0408f3"},"headers":[],"relativePath":"life/recipes/roasted-fish.md","filePath":"life/recipes/roasted-fish.md","lastUpdated":1795866905000}'),o={name:"life/recipes/roasted-fish.md"};function l(n,t,p,g,c,h){return i(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="烤鱼" tabindex="-1">烤鱼 <a class="header-anchor" href="#烤鱼" aria-label="Permalink to &quot;烤鱼&quot;">​</a></h1><div class="recipe-gallery"><img src="'+r+'" alt="烤鱼成品：不锈钢烤盘里开背黑鱼煎得金黄，浸在红油汤汁里，四周铺干豆腐条、土豆片、豆芽，撒辣椒段花椒香菜"></div><p>烤鱼分两段：鱼开背腌好、下锅煎到两面金黄皮脆，另一锅把火锅底料炒出红油、配菜煮一煮。最后配菜垫底铺盘，鱼往上放，浇汁撒料，端上桌还在咕嘟。</p><h2 id="用料" tabindex="-1">用料 <a class="header-anchor" href="#用料" aria-label="Permalink to &quot;用料&quot;">​</a></h2><p><strong>主料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>黑鱼</td><td>一条，一斤半左右最好；肉厚刺少，让摊主开背处理好</td></tr><tr><td>干豆腐</td><td>半张，切条，最吸汤汁</td></tr><tr><td>土豆</td><td>一个，切厚片，炖完不容易烂</td></tr><tr><td>豆芽</td><td>一小把，垫底最吸味</td></tr></tbody></table><p><strong>底料与调料</strong></p><table tabindex="0"><thead><tr><th>用料</th><th>说明</th></tr></thead><tbody><tr><td>火锅底料</td><td>一小块，红油和味道都靠它，不用再另调酱</td></tr><tr><td>干辣椒段</td><td>一把，怕辣就减半</td></tr><tr><td>花椒</td><td>一小把，青花椒更香</td></tr><tr><td>大蒜</td><td>一头，一半炒底料一半最后撒</td></tr><tr><td>生姜</td><td>一块，切片，腌鱼和煎鱼都用</td></tr><tr><td>洋葱</td><td>半个，切丝垫盘</td></tr><tr><td>料酒</td><td>腌鱼、炒料各一次</td></tr><tr><td>盐</td><td>腌鱼用</td></tr><tr><td>生抽</td><td>调味</td></tr><tr><td>食用油</td><td>煎鱼和炒底料都要多放</td></tr><tr><td>香菜、葱花</td><td>最后撒</td></tr></tbody></table><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><ol><li><p><strong>开背处理。</strong> 鱼让摊主从背部剖开、去干净内脏，回来自己再刮一遍腹内的黑膜，鱼身两面划几刀。黑膜是腥味来源，刮不干净后面调料再重也压不住。</p><figure class="recipe-shots"><img loading="lazy" src="'+a+'" alt="不锈钢盘里开背摊平的黑鱼，鱼皮灰黑带斑纹"></figure></li><li><p><strong>腌制。</strong> 鱼身抹盐、料酒，肚子里塞姜片葱段，腌 20 分钟。腌够时间鱼肉才紧实，煎的时候不容易散。</p></li><li><p><strong>切配菜。</strong> 干豆腐切条、土豆切厚片、豆芽洗净沥干。干豆腐切宽条才挂得住汤汁，土豆片厚一点不容易炖烂。</p></li><li><p><strong>炒底料。</strong> 锅里多放油，下火锅底料块小火炒化，再下干辣椒、花椒、姜蒜炒香。底料一定要小火慢慢化开，火大了直接糊底，整锅发苦。</p></li><li><p><strong>煮配菜。</strong> 加生抽和热水烧开，把干豆腐、土豆片、豆芽下锅煮几分钟，先入个底味。别煮太软，后面还要泡在汤汁里。</p></li><li><p><strong>煎鱼。</strong> 平底锅多放点油，鱼皮朝下先下锅，中火煎到金黄定型再翻面，两面都煎出焦脆的皮。鱼皮要擦干、锅要够热，别一放下去就动它。</p></li><li><p><strong>摆盘。</strong> 深盘或烤盘底部先铺洋葱丝和煮好的配菜，再把煎好的鱼放上去。配菜垫在底下吸汁，鱼别泡在汤里，皮才脆。</p></li><li><p><strong>浇汁撒料。</strong> 底料汤汁浇在鱼身上，撒熟芝麻、香菜、葱花，喜欢更辣的再撒一把干辣椒段。上桌前浇一勺热油更香。</p><figure class="recipe-shots"><img src="'+r+'" alt="烤鱼成品：不锈钢烤盘里开背黑鱼煎得金黄，浸在红油汤汁里，四周铺干豆腐条、土豆片、豆芽，撒辣椒段花椒香菜"></figure></li></ol><h2 id="关键点" tabindex="-1">关键点 <a class="header-anchor" href="#关键点" aria-label="Permalink to &quot;关键点&quot;">​</a></h2><ul><li><strong>黑膜刮干净</strong>：鱼腹内那层黑膜是腥味的大头，刮净比多放调料管用。</li><li><strong>腌够 20 分钟</strong>：时间短了鱼肉松散，煎完一夹就碎。</li><li><strong>鱼皮擦干、锅要热</strong>：鱼皮带水下锅必粘，粘了就破相。</li><li><strong>底料小火炒化</strong>：火锅底料一糊就发苦，红油也出不来。</li><li><strong>配菜垫底、鱼在上</strong>：鱼泡在汤里皮就软了。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">偷懒版</p><p>不想守锅煎鱼，可以用空气炸锅 200℃ 烤 20 分钟，或者锅里多放油半煎半炸。配菜懒得煮就直接铺盘，靠浇的汤汁焖着，多泡一会儿也能入味。</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">常见翻车</p><p></p><ul><li><strong>鱼皮粘锅撕破</strong>：鱼皮没擦干，或者锅不够热就下鱼。</li><li><strong>鱼肉散不成块</strong>：腌的时间不够，或者翻面翻太早。</li><li><strong>发苦</strong>：火锅底料炒糊了，或者干辣椒炒黑了。</li><li><strong>只有咸没有香</strong>：底料放太多、花椒辣椒放太少，香味压不住咸味。</li><li><strong>配菜寡淡</strong>：配菜没提前煮过直接铺盘，只靠浇的汤汁入味。</li></ul></div><p><a href="/life/recipes/">← 回菜谱总览</a></p>',15)])])}const _=s(o,[["render",l]]);export{u as __pageData,_ as default};
